import{_ as s,a0 as i,w as u,s as l,I as p,x as o,a1 as e,A as r,ao as b}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"在Ubuntu中将Dropbox文件夹放移动硬盘上 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中将Dropbox文件夹放移动硬盘上 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中将Dropbox文件夹放移动硬盘上 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中将Dropbox文件夹放移动硬盘上 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Move Dropbox’s Folder To An External Drive In Ubuntu","title":"在Ubuntu中将Dropbox文件夹放移动硬盘上","tag":"201401","desc":""},"relativePath":"201401/Move Dropbox’s Folder To An External Drive In Ubuntu.md","filePath":"[post].md"}'),a={name:"201401/Move Dropbox’s Folder To An External Drive In Ubuntu.md"};function d(x,t,g,w,m,D){const n=i("Link");return u(),l("div",null,[t[14]||(t[14]=p("h1",{id:"在ubuntu中将dropbox文件夹放移动硬盘上",tabindex:"-1"},[o("在Ubuntu中将Dropbox文件夹放移动硬盘上 "),p("a",{class:"header-anchor",href:"#在ubuntu中将dropbox文件夹放移动硬盘上","aria-label":"Permalink to “在Ubuntu中将Dropbox文件夹放移动硬盘上”"},"​")],-1)),p("p",null,[t[1]||(t[1]=o("几个星期前，我们展示了如何[在Microsoft Windows中移动Dropbox文件夹到一个移动硬盘] ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/11/daily-windows-tips-move-dropbox-folder-to-external-drive/"},{default:r(()=>[...t[0]||(t[0]=[o("1",-1)])]),_:1}),t[2]||(t[2]=o("。该教程获得一致好评。对于使用Ubuntu操作系统的用户来说同样适用。",-1))]),t[15]||(t[15]=b(`<p>这个简短的教程将告诉你如何在Ubuntu下轻松地将Dropbox文件夹移动到另一个位置。</p><p>我写这些教程的原因是，几个月前我收到了一台全新的只有128GB SSD硬盘的惠普EliteBook笔记本电脑。我爱这台快速且性能良好的电脑。</p><p>它的缺点是，本地存储太小，无法处理我所有的东西。除了我的本地应用程序和数据，我在我的Dropbox也有几个GB大小的文件。</p><p>所以，当我同步我的Dropbox帐号并下载它的所有内容，我的HP EliteBook，完全消耗掉整个本地磁盘。</p><p>唯一的解决办法是，不使用本地存储磁盘直接将Dropbox文件夹移动到一个外部的移动硬盘上中。</p><p>如果你发现自己也有类似的问题，无论是使用Windows还是Ubuntu，请按照下列步骤，以腾出本地磁盘上的空间。在Ubuntu中开始移动Dropbox文件夹，首先插入外部存储器。（译注：本例并非真实的外部移动硬盘，而是在vbox测试环境中测试。）</p><p>插入磁盘后，进入Unity Dash 并搜索Disks。打开它并选择你希望适用的外部驱动器，点击 <strong>Tools –&gt; Format</strong></p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder3.png" alt=""></p><p>下一步，格式化驱动器的文件系统为<strong>NTFS</strong>格式。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder4.png" alt=""></p><p>格式化之后，选择 <strong>Tools –&gt; Mount Options</strong></p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder5.png" alt=""></p><p>然后指定相应的选项，如下图所示：安装点（准备将Dropbox的文件夹放到这里），文件系统类型，以及下面的图片中的其他选项。保存它时，你就大功告成了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder6.png" alt=""></p><p>在此之后，退出Dropbox的服务并在默认位置（/home/用户名/Dropbox）删除当前的Dropbox文件夹（译注：在Dropbox完全移动好之前，我不建议你如本文一样删除原来的文件夹，而是将文件夹改名，要不万一出错呢？）。当您再次启动Dropbox的服务时，它会提醒你缺少的文件夹。点击重新链接按钮以指定新的位置（就是你的移动硬盘上的新位置）。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder.png" alt=""></p><p>当提示选择安装类型，选择‘<strong>Advanced’</strong>并指定位置安装Dropbox文件夹。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder1.png" alt=""></p><p>设置完毕后，重新启动，如果Dropbox的不会提示你缺少文件夹，那么就成功了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/dropboxubuntumissingfolder2.png" alt=""></p><p>教程就是这样！</p><p>如果没有安装NTFS-3G，运行这个命令来安装它。</p><pre><code>sudo apt-get install ntfs-3g
</code></pre><hr>`,24)),p("p",null,[t[4]||(t[4]=o("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/12/move-dropboxs-folder-to-an-external-drive-in-ubuntu/"},{default:r(()=>[...t[3]||(t[3]=[o("http://www.liberiangeek.net/2013/12/move-dropboxs-folder-to-an-external-drive-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[7]||(t[7]=o("译者：",-1)),e(n,{href:"https://github.com/yechunxiao19"},{default:r(()=>[...t[5]||(t[5]=[o("乌龙茶",-1)])]),_:1}),t[8]||(t[8]=o(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[o("Linux中国",-1)])]),_:1}),t[13]||(t[13]=o(" 荣誉推出",-1))])])}const k=s(a,[["render",d]]);export{v as __pageData,k as default};
